vec2 dir8[8]=vec2[](vec2(1.0,0.0),vec2(1.0,1.0),vec2(0.0,1.0),vec2(1.0,-1.0),vec2(0.0,-1.0),vec2(-1.0,-1.0),vec2(-1.0,0.0),vec2(-1.0,1.0));
vec2 dir4_1[4]=vec2[](vec2(1.0,1.0),vec2(-1.0,-1.0),vec2(1.0,-1.0),vec2(-1.0,1.0));

float shape(vec2 uv,vec2 dir){

    vec2 l = uv-0.5;
    l+=dir;
    float pix =0.02;
    float thin=0.05;
    float radius=0.60;
    float offset=curl_random(iTime,0.,100.0);
    radius+=(offset-0.5)*radius;
    //circles https://youtu.be/2R7h76GoIJM?t=1027
    float a= smoothstep(pix,-pix,abs(length(l)-radius)-thin);
    radius=1.0-radius;
    float c= smoothstep(radius+thin+pix,
                      radius+thin-pix,
                      length(l));

    float d= smoothstep(radius-thin+pix,
                      radius-thin-pix,
                      length(l));
    return max(a,c-d);
}

float shape_4(vec2 st,int type){
    float color=0.0;
    #define loop2 2
    if(type<1)
        for(int i=0;i<2;i++)
            color=max(color,shape(st,dir4_1[i]/2.0)); 
    else if(type<2)
        for(int i=2;i<4;i++)
            color=max(color,shape(st,dir4_1[i]/2.0));
    else
        for(int i=0;i<4;i++)
            color=max(color,shape(st,dir4_1[i]/2.0));
    return color;
}
